from itertools import product
# elements: types over (card, parcel, envelope, bag, postcard); enumerate models with up to 4 items
types=[t for t in product([0,1],repeat=5) if not(t[0] and t[1]) and (not t[0] or t[2])]
from itertools import combinations
def holds(m):
    return any(t[2] and t[3] for t in m)
res={'I':True,'II':True,'III':True}
for r in range(1,4):
    for m in combinations(types,r):
        if not holds(m): continue
        if any(t[2] and t[1] for t in m): res['I']=False
        if any(t[0] and t[3] for t in m): res['II']=False
        if not all(not t[3] or t[4] for t in m) or not any(t[3] and t[4] for t in m): res['III']=False
assert res=={'I':False,'II':False,'III':False}

